import heapq


def _dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[None] + [row["version"] for row in packages[name]]
                   for name in names]
        best_score = None
        best = None

        for values in product(*choices):
            selected = {name: version for name, version in zip(names, values)
                        if version is not None}
            rows = {}
            valid = True
            for name, version in selected.items():
                if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                    valid = False
                    break
                rows[name] = next((r for r in packages[name]
                                   if r["version"] == version), None)
                if rows[name] is None:
                    valid = False
                    break
            if not valid:
                continue

            edges = {name: [] for name in selected}
            for root, bounds in data["roots"].items():
                version = selected.get(root)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            reached = set()
            stack = list(data["roots"])
            while stack and valid:
                name = stack.pop()
                if name in reached:
                    continue
                reached.add(name)
                if name not in selected:
                    valid = False
                    break
                row = rows[name]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    child = dep["name"]
                    version = selected.get(child)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(child)
                    stack.append(child)
            if not valid or reached != set(selected):
                continue

            # Reject cycles in the active dependency graph.
            state = {}
            def visit(node):
                if state.get(node) == 1:
                    return False
                if state.get(node) == 2:
                    return True
                state[node] = 1
                for child in edges[node]:
                    if not visit(child):
                        return False
                state[node] = 2
                return True
            if not all(visit(node) for node in edges):
                continue

            score = tuple(selected.get(name, -1) for name in names)
            if (best_score is None or
                (score < best_score if preference == "minimum" else score > best_score)):
                best_score, best = score, selected

        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _ledger(data):
    def rounded(n, d, mode):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = sorted(j["id"] for j in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            for duration, after in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, after)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, after))
    return {"arrival": None}


